//! Almanac's data model and sync protocol.
//!
//! The server uses these types directly. The clients get them as TypeScript,
//! generated by `bun run gen:types` into `packages/types`.
//!
//! Everything a workspace keeps syncs: its topics, their blocks, points, reminders
//! and questions, the talks they were kept from, and its members.
//!
//! On the wire, field names are snake_case, the same as the database columns.

mod account;
mod model;
mod protocol;
mod talk;
mod topic;
mod user;

pub use account::{
    ClaudeCodeInfo, ClaudeKeyInfo, Me, MemberInfo, Role, SetClaudeKeyRequest, SetClaudeWebRequest,
    UpdateMemberRequest, UpdateProfileRequest, UpdateWorkspaceRequest, UserInfo, WorkspaceInfo,
    clean_name, normalize_email, url_key_from,
};
pub use model::{Actor, ModelKind, Validate, ValidationError, Write};
pub use protocol::{
    ApiError, Bootstrap, Operation, ServerMessage, SyncAction, SyncEntry, Transaction,
    TransactionResult,
};
pub use talk::{
    AskRequest, BlockWas, LayoutMove, Message, MessageCreate, MessagePatch, PageLayout, Photo,
    PhotoUpload, PointWas, Proposal, ProposedPoint, ProposedReminder, Source, Talk, TalkCreate,
    TalkPatch, TopicChange,
};
pub use topic::{
    BLOCK_KINDS, BLOCK_VIEWS, BLOCK_WIDTHS, Block, BlockCreate, BlockPatch, FACET_ICONS, Facet,
    ICONS, KINDS, LOOKS, MOST_FACETS, Point, PointCreate, PointPatch, Question, QuestionCreate,
    QuestionPatch, Reminder, ReminderCreate, ReminderPatch, STICKS_TO_MAX, StartTopicRequest,
    StartedTopic, TEMPLATE_NAMES, TEMPLATES, Topic, TopicCreate, TopicPatch, template, width_of,
};
pub use user::User;
